// 工具函数，更改树形下拉数据的值
export const formatTreeData = (data,props) =>{
    return data.map(item => {
        if (item.children?.length > 0) {
            item.children = formatTreeData(item.children,props)
        }
        return {
            label: item[props?.label || 'label'],
            value: item[props?.value || 'value'],
            children: item[props?.children || 'children']
        }
    })
}

function transformToTree(data) {
    return Object.entries(data).map(([key, value]) => {
        const node = {
            name: key,
            value: key,
            children: []
        };
        if (Array.isArray(value)) {
            node.children = value.map((item, i) => {
                return {
                    name: item.name,
                    value: item.name
                }
            });
        } else if (typeof value === 'string') {
            // 如果值是字符串，保持 children 为空数组
            node.children = [];
        }

        return node;
    });
}

