export const useSolarTermData = (baseURL) => {
    const data = ref([])

    // 获取节气数据
    const getData = () => {
        extendRequest(ajaxPromise,[{
            url: baseURL + '/commonUtil/getInfoFromRedisByKey',
            method: 'get',
            data: {key: 'solar_term_festival_info'},
            clearParamsFlag:false
        }]).then(res=>{
            if(res.code==200){
                data.value = JSON.parse(res.data) || [];
                localStorage.setItem('solar_term_festival_info', res.data);
            }
        });
    }

    // 从浏览器中获取数据
    try{
        let cache = localStorage.getItem('solar_term_festival_info');
        if(cache){
            data.value = JSON.parse(cache)||[];
        }
    }catch(e){}

    return {
        data,
        getData
    }
